use vstd::prelude::*;

verus! {

spec fn is_odd(x: int) -> bool {
    x % 2 != 0
}

fn find_first_odd(a: &[i32]) -> (found: bool, idx: usize)
    ensures
        // If not found, there are no odd elements.
        (!found) ==> (forall |j: int|
            0 <= j < a@.len() ==> !is_odd(a@[j] as int)
        ),
        // If found, idx is in bounds, points to an odd element,
        // and all earlier elements are not odd (i.e., first odd).
        found ==> (
            (idx as int) < a@.len()
            && is_odd(a@[idx as int] as int)
            && (forall |j: int| 0 <= j < (idx as int) ==> !is_odd(a@[j] as int))
        ),
        // Matches implementation's default index when not found.
        (!found) ==> idx == 0,
{
    for (i, &x) in a.iter().enumerate()
        invariant
            // All already-visited positions have been checked and are not odd.
            forall |j: int| 0 <= j < (i as int) ==> !is_odd(a@[j] as int),
            // The loop index stays within bounds.
            (i as int) <= a@.len(),
    {
        if x % 2 != 0 {
            // Relate `x` from iteration to the spec view of the slice.
            assert(a@[i as int] == x);
            assert(is_odd(a@[i as int] as int));
            return (true, i);
        } else {
            // Establish the new fact for the just-checked element.
            assert(a@[i as int] == x);
            assert(!is_odd(a@[i as int] as int));
        }
    }
    (false, 0)
}

}

